-- 3) Facciones 2517/2571 (este cliente no las conoce) -> 35, como el resto de las que no tienen
--    facción válida. La facción real no se conoce y queda anotada en PENDIENTES §2 (P5/O5).
UPDATE `creature_template` SET `faction` = 35 WHERE `entry` IN (181016,186317,186324,186326,186331,186429,186430,186447,186451,186763,186764,186765,187187,187189,188445,189461,189713,191014,191015,191021,191038,191039,191042,191043,191044,191851,196995) AND `faction` IN (2517, 2571);


-- 4) Las 43 plantillas que quedaron SIN ninguna fila de modelo (su unica fila apuntaba a un display que el
--    cliente no trae y se borro arriba): se les pone el display 11686 por REGLA (toda plantilla sin fila de
--    modelo), que es lo que el core ya hacia al descartar el display invalido (criatura invisible).
--    Idempotente: la segunda pasada no inserta nada.
SELECT ct.`entry`, 0, 11686, 1, 1, 0 FROM `creature_template` ct
LEFT JOIN `creature_template_model` m ON m.`CreatureID` = ct.`entry` WHERE m.`CreatureID` IS NULL;
